package fs

import (
	"context"
	"testing"
	"time"

	"go.flipt.io/flipt/internal/containers"
	"go.uber.org/zap"
)

type Poller struct {
	logger *zap.Logger

	interval time.Duration
	notify   func(modified bool)
}

func WithInterval(interval time.Duration) containers.Option[Poller] {
	return func(p *Poller) {
		p.interval = interval
	}
}

func WithNotify(t *testing.T, n func(modified bool)) containers.Option[Poller] {
	t.Helper()
	return func(p *Poller) {
		p.notify = n
	}
}

func NewPoller(logger *zap.Logger, opts ...containers.Option[Poller]) *Poller {
	p := &Poller{
		logger:   logger,
		interval: 30 * time.Second,
	}
	containers.ApplyAll(p, opts...)
	return p
}

// Poll is a utility function for a common polling strategy used by lots of declarative
// store implementations.
func (p *Poller) Poll(ctx context.Context, update func(context.Context) (bool, error)) {
	ticker := time.NewTicker(p.interval)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			modified, err := update(ctx)
			if err != nil {
				p.logger.Error("error getting file system from directory", zap.Error(err))
				continue
			}

			if p.notify != nil {
				p.notify(modified)
			}

			if !modified {
				p.logger.Debug("skipping snapshot update as it has not been modified")
				continue
			}

			p.logger.Debug("snapshot updated")
		}
	}
}

package s3

import (
	"context"
	"sync"
	"time"

	"github.com/aws/aws-sdk-go-v2/config"
	"github.com/aws/aws-sdk-go-v2/service/s3"

	"go.flipt.io/flipt/internal/containers"
	"go.flipt.io/flipt/internal/storage"
	storagefs "go.flipt.io/flipt/internal/storage/fs"
	"go.uber.org/zap"
)

var _ storagefs.SnapshotStore = (*SnapshotStore)(nil)

// SnapshotStore represents an implementation of storage.SnapshotStore
// This implementation is backed by an S3 bucket
type SnapshotStore struct {
	logger *zap.Logger
	s3     *s3.Client

	mu   sync.RWMutex
	snap storage.ReadOnlyStore

	endpoint string
	region   string
	bucket   string
	prefix   string

	pollOpts []containers.Option[storagefs.Poller]
}

// View accepts a function which takes a *StoreSnapshot.
// The SnapshotStore will supply a snapshot which is valid
// for the lifetime of the provided function call.
func (s *SnapshotStore) View(fn func(storage.ReadOnlyStore) error) error {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return fn(s.snap)
}

// NewSnapshotStore constructs a Store
func NewSnapshotStore(ctx context.Context, logger *zap.Logger, bucket string, opts ...containers.Option[SnapshotStore]) (*SnapshotStore, error) {
	s := &SnapshotStore{
		logger: logger,
		bucket: bucket,
		pollOpts: []containers.Option[storagefs.Poller]{
			storagefs.WithInterval(60 * time.Second),
		},
	}

	containers.ApplyAll(s, opts...)

	cfg, err := config.LoadDefaultConfig(context.Background(),
		config.WithRegion(s.region))
	if err != nil {
		return nil, err
	}

	var s3Opts []func(*s3.Options)
	if s.endpoint != "" {
		s3Opts = append(s3Opts, func(o *s3.Options) {
			o.BaseEndpoint = &s.endpoint
			o.UsePathStyle = true
			o.Region = s.region
		})
	}
	s.s3 = s3.NewFromConfig(cfg, s3Opts...)

	// fetch snapshot at-least once before returning store
	// to ensure we have some state to serve
	if _, err := s.update(ctx); err != nil {
		return nil, err
	}

	go storagefs.NewPoller(s.logger, s.pollOpts...).Poll(ctx, s.update)

	return s, nil
}

// WithPrefix configures the prefix for s3
func WithPrefix(prefix string) containers.Option[SnapshotStore] {
	return func(s *SnapshotStore) {
		s.prefix = prefix
	}
}

// WithRegion configures the region for s3
func WithRegion(region string) containers.Option[SnapshotStore] {
	return func(s *SnapshotStore) {
		s.region = region
	}
}

// WithEndpoint configures the region for s3
func WithEndpoint(endpoint string) containers.Option[SnapshotStore] {
	return func(s *SnapshotStore) {
		s.endpoint = endpoint
	}
}

// WithPollOptions configures the poller options used when periodically updating snapshot state
func WithPollOptions(opts ...containers.Option[storagefs.Poller]) containers.Option[SnapshotStore] {
	return func(s *SnapshotStore) {
		s.pollOpts = append(s.pollOpts, opts...)
	}
}

// Update fetches a new snapshot and swaps it out for the current one.
func (s *SnapshotStore) update(context.Context) (bool, error) {
	fs, err := NewFS(s.logger, s.s3, s.bucket, s.prefix)
	if err != nil {
		return false, err
	}

	snap, err := storagefs.SnapshotFromFS(s.logger, fs)
	if err != nil {
		return false, err
	}

	s.mu.Lock()
	s.snap = snap
	s.mu.Unlock()

	return true, nil
}

// String returns an identifier string for the store type.
func (s *SnapshotStore) String() string {
	return "s3"
}

package git

import (
	"context"
	"errors"
	"fmt"
	"io/fs"
	"sync"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/config"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/transport"
	"github.com/go-git/go-git/v5/storage/memory"
	"go.flipt.io/flipt/internal/containers"
	"go.flipt.io/flipt/internal/gitfs"
	"go.flipt.io/flipt/internal/storage"
	storagefs "go.flipt.io/flipt/internal/storage/fs"
	"go.uber.org/zap"
)

// ensure that the git *Store implements storage.Store
var _ storagefs.SnapshotStore = (*SnapshotStore)(nil)

// SnapshotStore is an implementation of storage.SnapshotStore
// This implementation is backed by a Git repository and it tracks an upstream reference.
// When subscribing to this source, the upstream reference is tracked
// by polling the upstream on a configurable interval.
type SnapshotStore struct {
	logger *zap.Logger
	repo   *git.Repository

	mu   sync.RWMutex
	snap storage.ReadOnlyStore

	url             string
	ref             string
	hash            plumbing.Hash
	auth            transport.AuthMethod
	caBundle        []byte
	insecureSkipTLS bool
	pollOpts        []containers.Option[storagefs.Poller]
}

// WithRef configures the target reference to be used when fetching
// and building fs.FS implementations.
// If it is a valid hash, then the fixed SHA value is used.
// Otherwise, it is treated as a reference in the origin upstream.
func WithRef(ref string) containers.Option[SnapshotStore] {
	return func(s *SnapshotStore) {
		if plumbing.IsHash(ref) {
			s.hash = plumbing.NewHash(ref)
			return
		}

		s.ref = ref
	}
}

// WithPollOptions configures the poller used to trigger update procedures
func WithPollOptions(opts ...containers.Option[storagefs.Poller]) containers.Option[SnapshotStore] {
	return func(s *SnapshotStore) {
		s.pollOpts = append(s.pollOpts, opts...)
	}
}

// WithAuth returns an option which configures the auth method used
// by the provided source.
func WithAuth(auth transport.AuthMethod) containers.Option[SnapshotStore] {
	return func(s *SnapshotStore) {
		s.auth = auth
	}
}

// WithInsecureTLS returns an option which configures the insecure TLS
// setting for the provided source.
func WithInsecureTLS(insecureSkipTLS bool) containers.Option[SnapshotStore] {
	return func(s *SnapshotStore) {
		s.insecureSkipTLS = insecureSkipTLS
	}
}

// WithCABundle returns an option which configures the CA Bundle used for
// validating the TLS connection to the provided source.
func WithCABundle(caCertBytes []byte) containers.Option[SnapshotStore] {
	return func(s *SnapshotStore) {
		if caCertBytes != nil {
			s.caBundle = caCertBytes
		}
	}
}

// NewSnapshotStore constructs and configures a Store.
// The store uses the connection and credential details provided to build
// fs.FS implementations around a target git repository.
func NewSnapshotStore(ctx context.Context, logger *zap.Logger, url string, opts ...containers.Option[SnapshotStore]) (_ *SnapshotStore, err error) {
	store := &SnapshotStore{
		logger: logger.With(zap.String("repository", url)),
		url:    url,
		ref:    "main",
	}
	containers.ApplyAll(store, opts...)

	field := zap.Stringer("ref", plumbing.NewBranchReferenceName(store.ref))
	if store.hash != plumbing.ZeroHash {
		field = zap.Stringer("SHA", store.hash)
	}
	store.logger = store.logger.With(field)

	store.repo, err = git.Clone(memory.NewStorage(), nil, &git.CloneOptions{
		Auth:            store.auth,
		URL:             store.url,
		CABundle:        store.caBundle,
		InsecureSkipTLS: store.insecureSkipTLS,
	})
	if err != nil {
		return nil, err
	}

	// fetch snapshot at-least once before returning store
	// to ensure we have some state to serve
	if err := store.get(ctx); err != nil {
		return nil, err
	}

	// if the reference is a static hash then it is immutable
	// if we have already fetched it once, there is not point updating again
	if store.hash == plumbing.ZeroHash {
		go storagefs.
			NewPoller(store.logger, store.pollOpts...).
			Poll(ctx, store.update)
	}

	return store, nil
}

// String returns an identifier string for the store type.
func (*SnapshotStore) String() string {
	return "git"
}

// View accepts a function which takes a *StoreSnapshot.
// The SnapshotStore will supply a snapshot which is valid
// for the lifetime of the provided function call.
func (s *SnapshotStore) View(fn func(storage.ReadOnlyStore) error) error {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return fn(s.snap)
}

// update fetches from the remote and given that a the target reference
// HEAD updates to a new revision, it builds a snapshot and updates it
// on the store.
func (s *SnapshotStore) update(ctx context.Context) (bool, error) {
	if err := s.repo.Fetch(&git.FetchOptions{
		Auth: s.auth,
		RefSpecs: []config.RefSpec{
			config.RefSpec(fmt.Sprintf(
				"+%s:%s",
				plumbing.NewBranchReferenceName(s.ref),
				plumbing.NewRemoteReferenceName("origin", s.ref),
			)),
		},
	}); err != nil {
		if !errors.Is(err, git.NoErrAlreadyUpToDate) {
			return false, err
		}

		return false, nil
	}

	if err := s.get(ctx); err != nil {
		return false, err
	}

	return true, nil
}

// get builds a new store snapshot based on the configure Git remote and reference.
func (s *SnapshotStore) get(context.Context) (err error) {
	var fs fs.FS
	if s.hash != plumbing.ZeroHash {
		fs, err = gitfs.NewFromRepoHash(s.logger, s.repo, s.hash)
	} else {
		fs, err = gitfs.NewFromRepo(s.logger, s.repo, gitfs.WithReference(plumbing.NewRemoteReferenceName("origin", s.ref)))
	}
	if err != nil {
		return err
	}

	snap, err := storagefs.SnapshotFromFS(s.logger, fs)
	if err != nil {
		return err
	}

	s.mu.Lock()
	s.snap = snap
	s.mu.Unlock()

	return nil
}

package local

import (
	"context"
	"os"
	"sync"

	"go.flipt.io/flipt/internal/containers"
	"go.flipt.io/flipt/internal/storage"
	storagefs "go.flipt.io/flipt/internal/storage/fs"
	"go.uber.org/zap"
)

var _ storagefs.SnapshotStore = (*SnapshotStore)(nil)

// SnapshotStore implements storagefs.SnapshotStore which
// is backed by the local filesystem through os.DirFS
type SnapshotStore struct {
	logger *zap.Logger
	dir    string

	mu   sync.RWMutex
	snap storage.ReadOnlyStore

	pollOpts []containers.Option[storagefs.Poller]
}

// NewSnapshotStore constructs a new SnapshotStore
func NewSnapshotStore(ctx context.Context, logger *zap.Logger, dir string, opts ...containers.Option[SnapshotStore]) (*SnapshotStore, error) {
	s := &SnapshotStore{
		logger: logger,
		dir:    dir,
	}

	containers.ApplyAll(s, opts...)

	// seed initial state an ensure we have state
	// before returning
	if _, err := s.update(ctx); err != nil {
		return nil, err
	}

	go storagefs.
		NewPoller(logger, s.pollOpts...).
		Poll(ctx, s.update)

	return s, nil
}

// WithPollOptions configures poller options on the store.
func WithPollOptions(opts ...containers.Option[storagefs.Poller]) containers.Option[SnapshotStore] {
	return func(s *SnapshotStore) {
		s.pollOpts = append(s.pollOpts, opts...)
	}
}

// View passes the current snapshot to the provided function
// while holding a read lock.
func (s *SnapshotStore) View(fn func(storage.ReadOnlyStore) error) error {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return fn(s.snap)
}

// update fetches a new snapshot from the local filesystem
// and updates the current served reference via a write lock
func (s *SnapshotStore) update(context.Context) (bool, error) {
	snap, err := storagefs.SnapshotFromFS(s.logger, os.DirFS(s.dir))
	if err != nil {
		return false, err
	}

	s.mu.Lock()
	s.snap = snap
	s.mu.Unlock()

	return true, nil
}

// String returns an identifier string for the store type.
func (s *SnapshotStore) String() string {
	return "local"
}

